WHERE LOWER(TRIM(COALESCE("Year", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Included in MA", '')) = 'Yes' AND TRIM(COALESCE("Name of ICI", '')) = 'Nivolumab, Ipilimumab' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 3';

