WHERE LOWER(TRIM(COALESCE("Type of therapy", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Melanoma' AND TRIM(COALESCE("Included in MA", '')) = 'Yes' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 2';

SELECT "Clinical setting"
FROM clinical_trials
WHERE LOWER(TRIM(COALESCE("Clinical setting", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Melanoma' AND TRIM(COALESCE("Included in MA", '')) = 'Yes' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 2';

